// This file describes the platform tools of a space: the capabilities agents
// call through spaces.ask (tool + args) next to the space's tool bots. Each
// carries its schema and usage guidance, served to agents by spaces.tools_list.
package vmm

import "github.com/tradera/tradera/pkg/a2ui"

type Tool struct {
	Name        string         `json:"name"`
	Description string         `json:"description"`
	BotID       string         `json:"bot_id,omitempty"`
	Kind        string         `json:"kind,omitempty"`
	Parameters  map[string]any `json:"parameters,omitempty"`
	Usage       string         `json:"usage,omitempty"`
	Example     string         `json:"example,omitempty"`
	// Commands are the functions a connected app (a remote MCP server) offers,
	// each with its own arguments. An agent calls them one by one; a tool
	// without commands is asked in plain words.
	Commands []ToolCommand `json:"commands,omitempty"`
	// Frontend is the mode of a tool's frontend (static or generative), which
	// ui_compose can show people; empty when it has none.
	Frontend string `json:"frontend,omitempty"`
}

// ToolCommand is one function of a connected app.
type ToolCommand struct {
	Name        string         `json:"name"`
	Description string         `json:"description,omitempty"`
	Schema      map[string]any `json:"schema,omitempty"`
}

func str(description string) map[string]any {
	return map[string]any{"type": "string", "description": description}
}
func integer(description string) map[string]any {
	return map[string]any{"type": "integer", "description": description}
}
func boolean(description string) map[string]any {
	return map[string]any{"type": "boolean", "description": description}
}
func tool(name, description, usage, example string, properties map[string]any, required ...string) Tool {
	schema := map[string]any{"type": "object", "properties": properties}
	if len(required) > 0 {
		schema["required"] = required
	}
	return Tool{Name: name, Kind: "tool", Description: description, Usage: usage, Example: example, Parameters: schema}
}

// Builtins returns fresh schemas so callers cannot mutate shared contracts.
func Builtins() []Tool {
	return []Tool{
		tool("sandbox_exec", "Run a shell command in the shared workspace sandbox.", "Inspect files, run code, build, test and start services. Commands use POSIX /bin/sh; Bash brace expansion and Bash-only syntax are unavailable unless you explicitly invoke an installed Bash. Detach long-lived servers with stdin/stdout/stderr redirected to files, record their PID, and probe readiness. Every call starts a fresh shell in the run directory; cd and exported variables do not persist. Use explicit paths or cd within each command. Sandbox paths are not host paths; coordinate shared artifacts with teammates. Probe required utilities once; Node, Python, zip, browsers and GNU flags depend on the selected sandbox image. If a utility is unavailable, choose an available equivalent or install it when permitted; do not keep retrying the missing utility. After writing files, run focused checks rather than repeatedly dumping all source. Read exit codes and errors even if a later command returned exit=0.", `{"command":"pwd && ls -la"}`, map[string]any{"command": str("Shell command to execute."), "max_output_chars": integer("Optional observation limit, 1000..40000; default 40000. Use smaller limits for focused diagnostics.")}, "command"),
		tool("file_read", "Read an attached file, search sandbox source, or read numbered line ranges.", "Use file_id/url for attachments, or path for sandbox source; do not combine the two. For HTML static checks prefer inspect=true: returns actual markup inventory, ID/link checks and inline JavaScript syntax checks without executing scripts. Browser layout and interactions remain unverified. Inspection, search and line ranges cannot be combined. For targeted inspection use pattern (RE2 regex, or literal=true for exact text) with context_lines, or start_line/end_line. Search and ranges cannot be combined. Sandbox reads require sandbox access and return bounded, numbered source with the next range when needed. Prefer pattern search to locate relevant definitions, then small ranges for details. After an edit, use its returned source excerpt and run a focused check instead of rereading the whole file.", `{"path":"index.html","start_line":200,"end_line":300}`, map[string]any{"file_id": str("Workspace file ID."), "url": str("File ID or /v1/files/{id}/content."), "path": str("Alternative sandbox text path."), "start_line": integer("First sandbox line, one-based; default 1."), "end_line": integer("Last sandbox line, inclusive; default end of file."), "pattern": str("Optional RE2 regex search in sandbox source; excludes line ranges. Use | for alternatives."), "inspect": map[string]any{"type": "boolean", "description": "Return HTML structure and real inline JS syntax checks instead of source; path only."}, "literal": map[string]any{"type": "boolean", "description": "Treat pattern as literal text; default false (RE2 regex)."}, "context_lines": integer("Lines around search matches, 0..20; default 3."), "max_chars": integer("Optional text limit: attachments up to 100000, sandbox up to 30000; search defaults to 12000.")}),
		tool("file_edit", "Apply a targeted exact text replacement in an existing sandbox source file, without rewriting the whole file.", "Prefer this for corrections to existing source. Read the relevant range first; old_text must match exactly once. Include enough surrounding context to disambiguate. The host checks the observed source before an atomic file replacement, preserving permissions. The result includes numbered current source around the edit, so a successful edit needs no whole-file reread. Run focused checks afterward. Requires sandbox access.", `{"path":"index.html","old_text":"const delay = 100;","new_text":"const delay = 200;"}`, map[string]any{"path": str("Existing sandbox file path."), "old_text": str("Nonempty exact fragment, occurring once."), "new_text": str("Replacement fragment; empty deletes the match.")}, "path", "old_text", "new_text"),
		tool("file_send", "Attach a sandbox file, or package source files directly into an attached ZIP without installed archive utilities.", "Provide a sandbox path or base64 content, not both. To create a ZIP directly without shell utilities, provide files:[{path,name}] and name ending in .zip; include all source files and README. Archive member names are relative paths. Prefer paths to avoid embedding bytes. Actually attach requested deliverables; writing a filename in a message does not deliver it. Requires file/media intent in the triggering request.", `{"path":"/tmp/report.pdf","caption":"Completed report"}`, map[string]any{"path": str("File path inside the shared sandbox."), "content": str("Alternative base64 file bytes."), "name": str("Filename; defaults to path basename."), "mime": str("Optional MIME type."), "room": str("Optional room ID; defaults to the current room."), "caption": str("Optional attachment message."), "files": map[string]any{"type": "array", "description": "Alternative ZIP members, packaged and attached by the platform; no zip CLI needed.", "items": map[string]any{"type": "object", "properties": map[string]any{"path": str("Source sandbox path"), "name": str("Relative ZIP member path, defaults to basename")}, "required": []string{"path"}}}}),
		tool("file_upload", "Store a file in the workspace and return its file ID.", "Provide path or base64 content and a name. Storage does not post an attachment. Use file_send when the user needs delivery in chat. Requires file/media intent.", `{"path":"/tmp/data.csv","name":"data.csv"}`, map[string]any{"path": str("Sandbox file path."), "content": str("Alternative base64 bytes."), "name": str("Filename."), "mime": str("Optional MIME type."), "room": str("Optional room ID; defaults to the current room.")}),
		tool("image_generate", "Generate an image with the configured image model and attach it to the current chat.", "Use the built-in image model for requested raster visuals. Provide a detailed prompt. It posts the image itself; do not send it a second time. Requires explicit image/file intent and an available image provider. Audio/video generation has no dedicated built-in model tool; use supported sandbox software only when available.", `{"prompt":"A restrained editorial illustration of a solar-powered city","size":"1536x1024"}`, map[string]any{"prompt": str("Detailed image description."), "size": str("1024x1024, 1536x1024, 1024x1536 or auto."), "name": str("Optional filename."), "caption": str("Optional attachment message."), "room": str("Optional room ID; defaults to the current room.")}, "prompt"),
		tool("message_send", "Post a chat message or send a direct message packet.", "Use for progress, handoffs and results. body is text; room selects a workspace room, to selects a recipient account. Omit both to use the current room. The platform currently posts this channel as tradera. It is fire-and-forget, not a synchronous agent ask.", `{"body":"Analysis is ready for the implementation step."}`, map[string]any{"body": str("Message text."), "room": str("Optional workspace room ID."), "to": str("Optional recipient account ID.")}, "body"),
		tool("room_info", "Discover workspace people, agents and tools.", "Use IDs from the returned inventory; do not invent agent, file, room or task IDs. An optional room filters the inventory.", `{}`, map[string]any{"room": str("Optional room ID; omitted means workspace inventory.")}),
		tool("ask_user", "Prepare a clarification for the orchestrator.", "Ask when only the user can supply an essential input, choose between materially different outcomes, or authorize expanded scope. First inspect available context/tools for facts you can discover yourself. Explain why the answer matters and offer 2-3 concrete choices when useful, allowing a free-text answer. This prepares a question for Tradera; it does not synchronously receive an answer. End the invocation after this call and include the question in your reply; the host also reads the recorded question. Direct agent chats must surface it in their reply.", `{"question":"Which dataset should this report use?"}`, map[string]any{"question": str("Self-contained question explaining the missing input and its impact."), "options": map[string]any{"type": "array", "maxItems": 3, "items": map[string]any{"type": "string"}, "description": "Optional concrete choices; put the recommended choice first. Free text is always allowed."}}, "question"),
		tool("proxy_create", "Expose a sandbox HTTP service through the platform gateway.", "Build the app first, then pass the command that starts it as `start`: the platform runs it for you in the background (when nothing answers on the port yet), waits until the port answers and tells you whether it did. Do not start the service yourself with nohup or a trailing &, and never run a server in the foreground: that command only ends when it times out. The saved start command is also how the preview comes back by itself after the computer has slept. The service must listen on 0.0.0.0. Returns the gateway path and posts an open card, holding the sandbox awake for a bounded 30-minute preview window. Report that path and temporary lifetime, not sandbox localhost or an invented public URL. Use proxy_get(probe:true) for observed upstream HTTP evidence. For a framework that needs its public base path compiled into routes/assets (such as Next.js), create the proxy with preserve_path=true before its final build, configure that returned gateway prefix as the app base path, include it in manual API fetch URLs, and then start/probe the app. Reuse the already-reserved matching gateway during publication; creating another prefix after the build breaks its routes. Repeated path-preserving creation for the same caller, room and port reuses a stable gateway. Match the application root slash behavior to the gateway root and verify its redirects. In this mode the gateway forwards that prefix upstream and leaves application responses unchanged, apart from a small script in HTML pages that keeps stray root-relative navigation inside the prefix. Verify nested routes, assets and navigation, not just the root HTML.", `{"port":8080,"title":"Project preview"}`, map[string]any{"port": integer("Sandbox port, 1-65535."), "title": str("Optional preview title."), "room": str("Optional room ID; defaults to current room."), "preserve_path": boolean("Forward the returned gateway path upstream for apps configured with that public base path; default false strips it."), "start": str("The shell command that starts the service, run from /workspace (for example: npm --prefix /workspace/site start -- -p 3000 -H 0.0.0.0). Always pass it: the computer sleeps when idle and a new one has nothing running, so this is how the preview is started again when someone opens it. It must start the built app without rebuilding, stay in the foreground and listen on the port given here. Call proxy_create again with the same port to change it.")}, "port"),
		tool("proxy_list", "List gateway proxies in this workspace.", "Inspect existing previews before creating duplicates or deleting a proxy.", `{}`, map[string]any{}),
		tool("proxy_get", "Inspect or HTTP-probe one workspace gateway proxy.", "Use a proxy ID returned by proxy_list or creation. With probe:true, the host checks its persisted upstream tunnel and returns actual HTTP status, byte count and complete-body SHA256. Compare that hash to the served source. Credentials stay private. This does not test node gateway authentication or browser behavior; do not search sandbox environment variables for gateway credentials.", `{"id":"<proxy-id>","probe":true}`, map[string]any{"id": str("Proxy ID."), "probe": map[string]any{"type": "boolean", "description": "Perform a bounded HTTP GET of the persisted upstream tunnel without returning credentials or body."}}, "id"),
		tool("proxy_delete", "Remove a workspace gateway proxy.", "Delete only a proxy belonging to this workspace when the assigned task requires removal; this does not stop the underlying service.", `{"id":"<proxy-id>"}`, map[string]any{"id": str("Proxy ID.")}, "id"),
		tool("ui_compose", "Show people a widget in the room: a dashboard, chart, table or form built from A2UI components (charts, tables, stat tiles, graphs, grids…), filled with live data from the space's tools, which may embed tools' own frontends.", "Use when a visual answer serves people better than text: a dashboard, a comparison, a trend, a list of records, a form. data fills paths of the widget's data model by calling tools' microtools: [{path, tool: <bot_id>, microtool, args}]; bind components to those paths. To embed a tool's own frontend (tools listed with a frontend), add {\"id\":..., \"component\": \"ToolFrontend\", \"tool\": <bot_id>, \"height\": 360}; combine several tools' frontends, charts and tables in one widget to build bigger views. The widget is posted as your message; say in words what it shows too.\n"+a2ui.CatalogPrompt, `{"title":"Portfolio","components":[{"id":"root","component":"Column","children":["kpis","history","positions"]},{"id":"kpis","component":"Grid","children":["total","pnl"]},{"id":"total","component":"Stat","label":"Total value","value":{"path":"/summary/total"},"format":"currency:USD"},{"id":"pnl","component":"Stat","label":"Today","value":{"path":"/summary/pnl"},"format":"+currency:USD","delta":{"path":"/summary/pnl_pct"},"deltaFormat":"+percent:2"},{"id":"history","component":"Chart","type":"area","title":"Value, 30 days","data":{"path":"/history"},"x":"date","y":"value","xFormat":"date","yFormat":"compact"},{"id":"positions","component":"Table","data":{"path":"/positions"},"columns":[{"field":"symbol"},{"field":"value","type":"number","format":"currency"},{"field":"change","type":"trend","format":"percent:2"}]}],"data":[{"path":"/summary","tool":"<tool-bot-id>","microtool":"portfolio_summary","args":{}},{"path":"/history","tool":"<tool-bot-id>","microtool":"portfolio_history","args":{"days":30}},{"path":"/positions","tool":"<tool-bot-id>","microtool":"positions","args":{}}]}`, map[string]any{"title": str("Short title of the widget."), "components": map[string]any{"type": "array", "description": "A2UI components; the root has id root.", "items": map[string]any{"type": "object"}}, "data": map[string]any{"type": "array", "description": "Data bindings: {path, tool (bot id), microtool, args}.", "items": map[string]any{"type": "object"}}, "room": str("Optional room ID; defaults to the current room.")}, "components"),
		tool("routine_create", "Schedule a routine in the current room: once, every N seconds, or every day at a clock time.", "For \"every day at 9am\" use type periodic with at=\"09:00\" and timezone set to the person's IANA timezone (e.g. Europe/London): it is given in the context of your turn when known. If it is not known, finish whatever they asked for right now first (answer, tell the joke — post it with send_message), and only then ask for their timezone with ask_user, rather than assuming UTC or asking before helping. Use delayed with delay_sec only for a single run, and periodic with interval_sec for a plain repeat (every 10 minutes). A routine that must repeat must be periodic: a delayed one runs once and is done. List existing routines before creating another. Set target to a real bot ID: an agent receives task instructions, while the shared sandbox tool receives a bounded one-shot shell command. Use the observed sandbox bot ID for deterministic jobs that do not need an LLM. Omit target to execute through Tradera. The task is what runs each time, written as the instruction itself (e.g. \"Tell a new joke in the room\"), never about scheduling the next run. Creation returns the persisted schedule and its next run, not proof that an occurrence ran.", `{"name":"daily-joke","type":"periodic","at":"09:00","timezone":"Europe/London","task":"Tell a new joke in the room"}`, map[string]any{"name": str("Routine name."), "type": str("delayed (once) or periodic (repeats)."), "task": str("Instruction run each time."), "target": str("Bot ID to execute the routine."), "delay_sec": integer("Delay before a one-shot run."), "interval_sec": integer("Seconds between periodic runs."), "at": str("Daily clock time HH:MM (24h); makes it run every day at that time."), "timezone": str("IANA timezone for at, e.g. Europe/London or America/New_York.")}, "type", "task"),
		tool("routine_list", "List routines in the current room.", "Read persisted IDs, room, type, interval, target, task, status and last/next execution evidence before managing or verifying a routine.", `{}`, map[string]any{}),
		tool("routine_get", "Inspect one persisted routine in the current room.", "Verify the actual interval, target, task, status and last/next run. For a sandbox target the task must be raw shell code, without prose. A schedule alone does not prove execution.", `{"id":"<routine-id>"}`, map[string]any{"id": str("Routine ID from creation or routine_list.")}, "id"),
		tool("routine_update", "Update a routine in the current room without changing its ID.", "Use routine_get first. Provide only the fields to change; omitted fields stay unchanged. Updating reschedules the next occurrence from now. For a sandbox target, task is the exact executable shell command without explanatory prose. A new schedule does not prove execution.", `{"id":"<routine-id>","task":"cd /tmp/project && node scripts/update-news.mjs","interval_sec":600}`, map[string]any{"id": str("Routine ID."), "name": str("Optional new name."), "target": str("Optional new target bot ID."), "task": str("Optional replacement task, raw shell code for a sandbox target."), "delay_sec": integer("Optional positive delayed schedule in seconds."), "interval_sec": integer("Optional positive periodic interval in seconds."), "at": str("Optional daily clock time HH:MM (24h)."), "timezone": str("IANA timezone for at.")}, "id"),
		tool("routine_delete", "Delete a routine from the current room.", "Use an ID from routine_list; removal prevents future scheduled runs.", `{"id":"<routine-id>"}`, map[string]any{"id": str("Routine ID.")}, "id"),
	}
}

func Names() []string {
	var names []string
	for _, t := range Builtins() {
		names = append(names, t.Name)
	}
	return names
}
